#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) { // limit to match original implementation
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Pascal's triangle, printing n rows (0 .. n-1)
    unsigned long long row[61] = {0};
    row[0] = 1ULL;
    for (long i = 0; i < n; ++i) {
        // print current row
        for (long j = 0; j <= i; ++j) {
            printf("%lld", (long long)row[j]);
            putchar(' ');
        }
        putchar('\n');
        // compute next row in-place
        row[i + 1] = 1ULL;
        for (long j = i; j > 0; --j) {
            row[j] += row[j - 1];
        }
    }
    return 0;
}
